{
  "findings": [
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.data",
      "severity": "MEDIUM",
      "explanation": "Access logging is not enabled for this S3 bucket. Without access logging, it is difficult to track access patterns and detect unauthorized access."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "Ensure all data stored in the S3 bucket have versioning enabled",
      "resource": "aws_s3_bucket.data",
      "severity": "MEDIUM",
      "explanation": "Versioning is not enabled for this S3 bucket. Without versioning, it is not possible to recover from accidental deletions or overwrites of objects."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "Ensure that S3 buckets are encrypted with KMS by default",
      "resource": "aws_s3_bucket.data",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have server-side encryption enabled with a KMS key. This could lead to sensitive data being stored unencrypted."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.data",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have a Public Access Block configuration. Without this, the bucket could be accidentally exposed to the public."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "data" {
  bucket        = "${local.resource_prefix.value}-data"
  force_destroy = true

  tags = merge({
    Name        = "${local.resource_prefix.value}-data"
    Environment = local.resource_prefix.value
  }, {})

  logging {
    target_bucket = "${local.resource_prefix.value}-logs"
    target_prefix = "${local.resource_prefix.value}/"
  }

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm     = "aws:kms"
      }
    }
  }

  public_access_block {
    block_public_acls       = true
    block_public_policy     = true
    ignore_public_acls      = true
    restrict_public_buckets = true
  }
}

resource "aws_s3_bucket" "logs" {
  bucket        = "${local.resource_prefix.value}-logs"
  force_destroy = true

  tags = merge({
    Name        = "${local.resource_prefix.value}-logs"
    Environment = local.resource_prefix.value
  }, {})
}",
  "fix_summary": "Enabled access logging by adding a logging block and creating a dedicated logs bucket. Enabled versioning to protect against accidental deletions. Configured server-side encryption with KMS for data protection. Added a Public Access Block to prevent accidental public exposure."
}
